  { id: 3, name: 'Coffee Mug', category: 'Home', price: 12.5, inStock: true }
];

// Create typed column definitions array here
const columnDefinitions: ColumnDefInterface[] = [
  { header: 'ID', accessorKey: 'id' },
  { header: 'Name', accessorKey: 'name' },
  { header: 'Category', accessorKey: 'category' },
  { header: 'Price', accessorKey: 'price', cell: formatPrice },
  { header: 'In Stock', accessorKey: 'inStock' }
];

// Define a basic renderer function here
