  return (
    <div>
      <h2>Product Inventory</h2>
      <table>
        <thead>
          <tr>
            {columnDefinitions.map((col) => (
              <th key={col.accessorKey}>{col.header}</th>
            ))}
          </tr>
        </thead>
        <tbody>
